ALTER TABLE public.publisher_payment_policy DROP CONSTRAINT publisher_payment_policy_minimum_check, DROP CONSTRAINT publisher_payment_policy_verification_days_check;
ALTER TABLE public.publisher_payment_policy ADD CONSTRAINT payment_minimum_positive CHECK(minimum>0), ADD CONSTRAINT payment_hold_positive CHECK(verification_days>=1);
CREATE OR REPLACE FUNCTION public.payment_batch_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ DECLARE p public.publisher_payment_policy; BEGIN p:=public.payment_policy_current(); IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Earnings batches cannot be deleted'; END IF; IF TG_OP='INSERT' AND NEW.verification_ends_at<NEW.verification_started_at+make_interval(days=>p.verification_days) THEN RAISE EXCEPTION 'Mandatory verification hold required'; END IF; IF TG_OP='UPDATE' AND (NEW.verification_ends_at<OLD.verification_ends_at OR NEW.verification_started_at<OLD.verification_started_at) THEN RAISE EXCEPTION 'Verification clock cannot be shortened'; END IF; IF TG_OP='UPDATE' AND OLD.finalized_at IS NOT NULL AND (NEW.gross<>OLD.gross OR NEW.net<>OLD.net) THEN RAISE EXCEPTION 'Finalized financial history requires a separate reversal'; END IF; IF NEW.status='finalized' AND (NEW.verification_ends_at>now() OR NOT NEW.approved OR NEW.investigation_open OR NEW.reconciliation_open) THEN RAISE EXCEPTION 'Verification and reconciliation must complete before finalization'; END IF; RETURN NEW; END $$;
CREATE TRIGGER payment_batch_guard BEFORE INSERT OR UPDATE OR DELETE ON public.publisher_earnings_batches FOR EACH ROW EXECUTE FUNCTION public.payment_batch_guard();
CREATE OR REPLACE FUNCTION public.payment_adjustment_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Adjustments cannot be deleted'; END IF; IF NEW.amount<>OLD.amount OR NEW.batch_id<>OLD.batch_id OR NEW.user_id<>OLD.user_id OR NEW.reason<>OLD.reason OR NEW.evidence<>OLD.evidence OR NEW.evidence_key<>OLD.evidence_key OR OLD.reversed_at IS NOT NULL THEN RAISE EXCEPTION 'Adjustment evidence is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER payment_adjustment_guard BEFORE UPDATE OR DELETE ON public.publisher_earnings_adjustments FOR EACH ROW EXECUTE FUNCTION public.payment_adjustment_guard();